INSERT INTO normalization_rule (rule_id, rule_version, source_scale, description, rule_owner, formula_ref, status, created_date) VALUES ('R-D2S1', 1, 'd2_input', 'D2 kit INPUTS for a JOIN D2 kit -> RDR. IDENTITY_v1: rdr = source_value, in D2-native units exactly as the 1.13 table or the pinned build file states them. FENCED: the JOIN anchors (r_HP on kit damage to monsters, r_DMG on kit-life quantities, the yard key on distances) are applied at the adapter boundary (rulebook lever L-22), NEVER in the corpus; derived sheet quantities (life, defence, block ...) are computed by the binder/adapter and are NOT stored. Covers d2_input_base_item + d2_input_charstats + d2_input_hard_points + d2_input_item_stat + d2_input_level + d2_input_missile_param + d2_input_skill_param + d2_input_stat_points.', 'gamora', 'reincarnated-engine/src/reincarnated/simulation/math/join1-j4b-d2-stamping-2026-10-14-CORRIGENDUM-1.md', 'active', '2026-10-14');
INSERT INTO canon_corpus (kit_id, folk_name, game, corpus_bucket, source, provenance_tag, source_date, range_val, commit_val, prefix_conf_provenance, elem_raw, suffix_rekey_status, mech_note, flags, prov, grain, core_skills, core_skills_prov, corpus_class, original_element, court, roster_status, roster_status_note, roster_status_date) VALUES ('d2-fire-sorc-c14', 'Fire Sorceress -- Maxroll S14 Meteor build file, Standard variant (JOIN-1 J4b, legolas C-14)', 'd2', 'd2', 'c14-build-file', 'c14-build-file', '2026-10-14', 'ranged', 'instant', 'derived-c14-build-file', 'fire', 'descriptor-final', 'JOIN-1 J4b kit of record: the pinned Maxroll S14 build file (Standard), resolved in LoD 1.13 (legolas C-14). Castables Fire Ball, Meteor, Static Field. INPUTS ONLY in kit_numeric (VERBATIM planner + DATAMINED 1.13); the sheet is derived by the binder. Mercenary OUT (KP-436). Sibling of d2-fire-sorc (D2R web values), which is a different record and is not modified.', 'join1-j4b', 'c14;maxroll-planner-gca1a0l6;d2-113-txt', 'kit', '["Fire Ball", "Meteor", "Static Field"]', 'c14-build-file', 'record', 'fire', 'fire', 'parked', 'JOIN-1 J4b kit-of-record fixture (B0-N binder positive control for the D2 adapter). A second build of the d2-fire-sorc identity: parked so active-roster and atlas denominators do not double-count it.', '2026-10-14');
INSERT INTO kit_mapping (kit_id, mapping_json, grade, deviation_notes, terminal_state, mapping_provenance, authored_date) VALUES ('d2-fire-sorc-c14', '{"fidelity_notes": "JOIN-1 J4b kit of record (legolas C-14 build file, Standard variant; KP-435/436/437). Mapping grade NOT assigned here: owed after the B0-N numeric re-run and the J4b gate.", "skills": [{"geometry_value": "projectile", "skills_txt_id": 47, "source_skill": "Fire Ball"}, {"geometry_value": "ground_target_delayed", "skills_txt_id": 56, "source_skill": "Meteor"}, {"geometry_value": "circle", "skills_txt_id": 42, "source_skill": "Static Field"}]}', NULL, 'UNGRADED: the JOIN-1 J4b kit of record; its mapping grade is owed after the B0-N numeric re-run and the J4b gate, not assigned by the data steward.', NULL, 'c14-build-file', '2026-10-14');
